<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
define('RUBIZH_AUTH',true);require dirname(__DIR__).'/api/lib.php';require dirname(__DIR__).'/shop/store-lib.php';require_once dirname(__DIR__).'/staff/auth.php';require_once dirname(__DIR__).'/staff/schema.php';
try{$o=getopt('',['email:','name:','role:','reason:']);$email=mb_strtolower(trim((string)($o['email']??'')));$role=$o['role']??'MANAGER';$name=trim((string)($o['name']??''));$password=rtrim((string)stream_get_contents(STDIN),"\r\n");$reason=shopFinancialReason((string)($o['reason']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>254||mb_strlen($name)<2||mb_strlen($name)>120||!in_array($role,['OWNER','MANAGER','LOGISTICS','READ_ONLY'],true)||strlen($password)<12||strlen($password)>72)throw new RuntimeException('Invalid account input');$db=rubizhDatabaseConnect(cfg());if(!crmSchemaReady($db))throw new RuntimeException('CRM migration required');$id=bin2hex(random_bytes(16));$db->beginTransaction();try{$db->prepare('INSERT INTO rubizh_staff_users(id,email,name,password_hash,role,created_at,updated_at) VALUES(?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute([$id,$email,$name,password_hash($password,PASSWORD_BCRYPT,['cost'=>12]),$role]);crmAudit($db,null,'staff',$id,'staff.provision',[],['email'=>$email,'role'=>$role],$reason,null,'SYSTEM');$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}unset($password);echo json_encode(['id'=>$id,'email'=>$email,'role'=>$role],JSON_THROW_ON_ERROR)."\n";
